  \item[\textup{[WG13]}]\label{ref:p2-wilde-guha}
  M. M. Wilde and S. Guha, ``Polar Codes for Degradable Quantum Channels,''
  \emph{IEEE Transactions on Information Theory} \textbf{59}, 4718--4729
